  return AUDIT_MATRIX.flatMap(({ theme, scheme }) =>
    examples.map((example) => ({
      ...example,
      id: `${example.record}-${example.index}-${theme}-${scheme}`.toLowerCase(),
      theme,
      scheme,
    })),
  );
}

