  ? Object.fromEntries(
      readdirSync(utilitiesDir)
        .filter((f) => f.endsWith(".css"))
        .map((f) => f.replace(/\.css$/u, ""))
        .map((name) => [`utilities/${name}`, `generated/utilities/${name}.css`]),
