 const selected=resolveExampleTargets(entry.examples).automatica11y;
 if(selected.length!==1) throw Error(`${name}: expected one audit example`);
 const window=new Window();
 window.document.body.innerHTML=exampleHtml(entry.examples[selected[0]]);
 for(const mod of entry.modifiers){
  if(mod.alias?.canonical || mod.pattern || mod.name.includes('*')) continue;
  if(![...window.document.querySelectorAll(`.instui-${name}`)].some(el=>el.classList.contains(mod.name))) throw Error(`${name}: missing canonical modifier ${mod.name}`);
 }
 for(const control of window.document.querySelectorAll('input,textarea,select')){
  if(control.type==='hidden')continue;
  if(!control.labels?.length&&!control.hasAttribute('aria-label')&&!control.hasAttribute('aria-labelledby'))throw Error(`${name}: unnamed control ${control.outerHTML}`);
  if(control.hasAttribute('aria-invalid') && control.getAttribute('aria-invalid')==='true' && control.validity.valid)throw Error(`${name}: invalid control must be natively invalid`);
 }
 for(const el of window.document.querySelectorAll('.-disabled')){
  const control=el.matches('input,textarea,select')?el:el.querySelector('input,textarea,select');
  if(!control?.disabled)throw Error(`${name}: -disabled without disabled control`);
